// Each cross-section records the two visible banks of a walkable strip.
// Horizontal strips are sampled at x, vertical strips at y. Intersecting
// strips form a junction without making the rocks between its arms walkable.
export function across(samples) {
  return [...samples.map(([x, top]) => [x, top]), ...samples.map(([x,, bottom]) => [x, bottom]).reverse()];
}

export function along(samples) {
  return [...samples.map(([y, left]) => [left, y]), ...samples.map(([y,, right]) => [right, y]).reverse()];
}

